class MyVector(ABC):
    def __init__(self, *args: int):
        self.vals = args

    def manhattan_distance(self, other: 'MyVector') -> float:
        return sum(abs(a - b) for a, b in zip(self.vals, other.vals))

    def cosine_similarity(self, other: 'MyVector') -> float:
        # Calculate dot product
        dot_product = sum(a * b for a, b in zip(self.vals, other.vals))
        # Calculate magnitudes
        magnitude_self = sum(x**2 for x in self.vals)**0.5
        magnitude_other = sum(x**2 for x in other.vals)**0.5
        # Handle zero magnitudes to avoid division by zero
        if magnitude_self == 0 or magnitude_other == 0:
            return 0
        # Calculate cosine similarity
        return dot_product / (magnitude_self * magnitude_other)

    @abstractmethod
    def some_other_method(self) -> None:
