from typing import Literal, List

Op = Literal["+", "-", "*", "/"]
Token = int | Op


class PostfixParser:
    def parse(self, inputs: List[Token]) -> float:
        """parses a sequence of input tokens using postfix notation and computes the result"""

        def parseHelp(inputs: List[Token], stack: List[float]) -> float:
            if not inputs:
                if len(stack)!= 1:
                    raise ValueError("Malformed input: stack should contain exactly one element")
                return stack[0]
            next = inputs.pop()
            match next:
                case int():
                    stack.insert(0, next)
                case Op():
                    if len(stack) < 2:
                        raise ValueError("Malformed input: not enough operands for operator")
                    stack.insert(0, self._apply_operator(stack.pop(), stack.pop(), next))
                else:
                    raise ValueError("Malformed input: unknown token")
            return parseHelp(inputs, stack)

        def _apply_operator(op1: float, op2: float, op: Op) -> float:
            match op:
                case "+":
                    return op1 + op2
                case "-":
                    return op1 - op2
                case "*":
                    return op1 * op2
                case "/":
                    if op2 == 0:
                        raise ZeroDivisionError("Cannot divide by zero")
                    return op1 / op2

        return parseHelp(inputs, [])

